const easyPairs=[{icon:'🐱 🔊 ❓',q:'고양이는 어떻게 울어요?',a:'고양이는 야옹 하고 울어요. 가르릉 같은 다른 소리도 내요.'},{icon:'🐧 🪽 ❓',q:'펭귄은 날아요?',a:'펭귄은 하늘을 날지 못해요. 물속에서는 날개를 움직여 헤엄쳐요.'}];
const normalAnswer=answer;answer=q=>{const pair=easyPairs.find(p=>p.q===q);return pair?pair.a+'\n\n미리 준비한 시연 답변이에요. 다른 자료에서도 확인해 봐요.':normalAnswer(q)};
function renderEasy(){const root=$('easy-questions');root.replaceChildren();easyPairs.forEach(p=>{const wrap=document.createElement('div');wrap.className='easy-item';const b=document.createElement('button');b.className='easy-card';const icon=document.createElement('span');icon.className='easy-icon';icon.textContent=p.icon;const label=document.createElement('b');label.textContent=p.q;b.append(icon,label);b.onclick=()=>{$('question').value=p.q;$('question').focus()};const read=document.createElement('button');read.className='read';read.textContent='🔊';read.setAttribute('aria-label',p.q+' 소리로 듣기');read.onclick=()=>{if(!('speechSynthesis' in window)){read.textContent='읽기 미지원';return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(p.q);u.lang='ko-KR';u.rate=.8;speechSynthesis.speak(u)};wrap.append(b,read);root.append(wrap)})}
function reportRows(){return records.map((r,i)=>({title:`${i+1}. ${r.question}`,body:[`시연 답변: ${r.answer.replace(/\n\n[\s\S]*/,'')}`,`내 판단: ${r.judgment||'아직 남기지 않았어요.'}`,`확인 자료와 근거: ${r.reason||'기록하지 않았어요.'}`]}))}
function renderSummary(){const root=$('summary');root.replaceChildren();reportRows().forEach(row=>{const card=document.createElement('article');const h=document.createElement('h3');h.textContent=row.title;card.append(h);row.body.forEach(line=>{const p=document.createElement('p');p.textContent=line;card.append(p)});root.append(card)});$('result').hidden=false}
$('save-judgment').onclick=()=>{if(latest<0){$('judgment-status').textContent='먼저 질문을 보내고 답변을 읽어 주세요.';return}const selected=document.querySelector('[name=judgment]:checked');if(!selected){$('judgment-status').textContent='먼저 판단을 하나 골라 주세요.';return}records[latest].judgment=selected.value;records[latest].reason=$('reason').value.trim();$('judgment-status').textContent='🌷 이번 질문의 판단을 기록했어요. 아래에서 정리 파일을 받을 수 있어요.';renderSummary()};
// Browser-local, paginated image PDF: Korean glyphs are drawn by the browser.
async function createReportPdf(){await document.fonts.ready;const pages=[];let c,ctx,y;
function page(){c=document.createElement('canvas');c.width=1240;c.height=1754;ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#5b467a';ctx.font='bold 34px "Noto Sans KR",sans-serif';ctx.fillText('궁금한 교실 · 오늘의 배움 기록',80,100);ctx.fillStyle='#777';ctx.font='20px "Noto Sans KR",sans-serif';ctx.fillText('API 없는 시연 활동 | '+new Date().toLocaleDateString('ko-KR')+' | '+(pages.length+1)+'쪽',80,145);y=210}
function finish(){ctx.font='18px "Noto Sans KR",sans-serif';ctx.fillStyle='#666';ctx.fillText('AI도 실수할 수 있어요. 중요한 정보는 다른 자료에서 꼭 확인해요.',80,1685);pages.push(c.toDataURL('image/jpeg',.94))}
function line(text,bold=false){const size=bold?27:24;ctx.font=`${bold?'bold ':''}${size}px "Noto Sans KR",sans-serif`;let buffer='';const flush=()=>{if(y>1590){finish();page();ctx.font=`${bold?'bold ':''}${size}px "Noto Sans KR",sans-serif`}ctx.fillStyle=bold?'#57416e':'#30363b';ctx.fillText(buffer,80,y);y+=42;buffer=''};for(const ch of text){if(ch==='\n'){flush();continue}if(ctx.measureText(buffer+ch).width>1080)flush();buffer+=ch}if(buffer)flush();y+=12}
page();line('질문하고, 자료를 확인하고, 나의 생각을 남겼어요.');line('이 파일은 대화 내용을 모은 기록입니다. 답변은 준비된 시연 내용이며 검증된 정답이나 AI 요약이 아닙니다.');for(const row of reportRows()){line(row.title,true);for(const t of row.body)line(t);y+=22}finish();return jpegPagesPdf(pages)}
function jpegPagesPdf(pages){const encoder=new TextEncoder(),chunks=[],offsets=[0];let length=0;const push=x=>{const bytes=typeof x==='string'?encoder.encode(x):x;chunks.push(bytes);length+=bytes.length};const obj=(id,body)=>{offsets[id]=length;push(`${id} 0 obj\n`);push(body);push('\nendobj\n')};push('%PDF-1.4\n');obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,`<< /Type /Pages /Count ${pages.length} /Kids [${pages.map((_,i)=>`${3+i*3} 0 R`).join(' ')}] >>`);pages.forEach((url,i)=>{const n=3+i*3;const raw=atob(url.split(',')[1]);const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));obj(n,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /XObject << /Im0 ${n+1} 0 R >> >> /Contents ${n+2} 0 R >>`);offsets[n+1]=length;push(`${n+1} 0 obj\n<< /Type /XObject /Subtype /Image /Width 1240 /Height 1754 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${bytes.length} >>\nstream\n`);push(bytes);push('\nendstream\nendobj\n');const stream='q\n595.28 0 0 841.89 0 0 cm\n/Im0 Do\nQ\n';obj(n+2,`<< /Length ${encoder.encode(stream).length} >>\nstream\n${stream}endstream`)});const start=length,count=3+pages.length*3;push(`xref\n0 ${count}\n0000000000 65535 f \n`);for(let i=1;i<count;i++)push(String(offsets[i]).padStart(10,'0')+' 00000 n \n');push(`trailer\n<< /Size ${count} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`);return new Blob(chunks,{type:'application/pdf'})}
$('download-pdf').onclick=async()=>{if(!records.some(r=>r.judgment)){return}const b=$('download-pdf');b.disabled=true;$('pdf-status').textContent='정리 파일을 만들고 있어요…';try{renderSummary();const blob=await createReportPdf();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='궁금한교실_배움기록.pdf';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);$('pdf-status').textContent='PDF 파일을 준비했어요. 다운로드 목록을 확인해 주세요.'}catch(e){$('pdf-status').textContent='파일을 만들지 못했어요. 다시 눌러 주세요.'}finally{b.disabled=false}};renderEasy();
